B.a27=s(["Pemfigus vulgaris: IgG anti-desmoglein 3; intraepidermal b\xfcller; a\u011f\u0131z mukozas\u0131 s\u0131k; Nikolsky (+)","B\xfcll\xf6z pemfigoid: IgG anti-BP180/230; subepidermal b\xfcller; ya\u015fl\u0131; gergin b\xfcller; Nikolsky (-)","Dermatitis herpetiformis: IgA anti-doku transglutaminaz; dirsek+diz+skalp; vezik\xfcl + ka\u015f\u0131nt\u0131; \xe7\xf6lyak ili\u015fkili","SLE deri: Kelebek eritem (malar rash) + fotosensitivite + disko lupus + oral \xfclser","Skleroderma: Y\xfczde sertlik + a\u011f\u0131z a\xe7\u0131l\u0131m\u0131 azalma + Raynaud; sistemik formlarda i\xe7 organ tutulumu","Vitiligo: Melanosit y\u0131k\u0131m\u0131; depigmente beyaz mak\xfcllar; Koebner +; tiroit otoimm\xfcn ile birliktelik"],t.s)
B.ag1=new A.D("B\xfcll\xf6z & Otoimm\xfcn Deri Hastal\u0131klar\u0131",B.a27)
B.a5q=s(["\u0130mpetigo: S. aureus veya S. pyogenes; bal rengi kabuklu vezik\xfclop\xfcst\xfcller; \xe7ocuklarda; topikal mupirosin","Sel\xfclit: Deri + subkutan doku; S. aureus / S. pyogenes; eritlem + \u0131s\u0131 + \xf6dem; IV/PO penisilin veya dikloksasilin","Erizipel: Y\xfczeyel sel\xfclit; parlak k\u0131rm\u0131z\u0131 y\xfcksek s\u0131n\u0131rl\u0131; S. pyogenes; penisilin",'Nekrotizan fasiit: Derin + h\u0131zl\u0131 yay\u0131lan; "zehirli" a\u011fr\u0131; krepitasyon; acil debridman + geni\u015f spektrum AB',"Herpes zoster (shingles): VZV reaktivasyonu; dermatomal vezik\xfcller; a\u011fr\u0131 belirgin; asiklovir + gabapentin","Tinea: Dermatofit; corporis (g\xf6vde), pedis (ayak), capitis (skalp), unguium (t\u0131rnak); topikal/sistemik antifungal","Skabies: Sarcoptes scabiei; gece ka\u015f\u0131nt\u0131; parmak aras\u0131 + bilek; t\xfcm aile tedavi; permetrin krem"],t.s)
B.ahA=new A.D("Deri Enfeksiyonlar\u0131",B.a5q)
B.a8l=s(["Bazal h\xfccreli karsinom: En s\u0131k deri kanseri; inci gibi pap\xfcl + telenjiektazi; UV maruziyeti; lokal invazif; eksizyzon","Yass\u0131 h\xfccreli karsinom: 2. s\u0131k; aktenik keratoz \xfczerinde geli\u015fir; kabar\u0131k \xfclsere lezyon; metastaz riski daha y\xfcksek","Melanom: Melanositten; ABCDE (Asimetri, Kenard\xfczensizlik, Color farkl\u0131l\u0131k, Diameter>6mm, Evolving); Clark/Breslow derinlik","Melanom tedavi: Geni\u015f eksizyon; sentinel lenf nodu biyopsisi; metastatik \u2192 anti-PD1 (nivolumab) + BRAF inhibit\xf6r\xfc","Aktinik keratoz: Premalign; skuaml\u0131 plak; g\xfcne\u015f hasarl\u0131 deride; 5-FU/imikimod topikal veya kriyoterapi","Kaposi sarkomu: HHV-8; AIDS ili\u015fkili; mor-k\u0131rm\u0131z\u0131 nod\xfcller; ART ile regrese olabilir","Dermoskopi: Deri t\xfcm\xf6r\xfc de\u011ferlendirme alt\u0131n standard\u0131; ABCD kural\u0131 dermoskopik versiyon"],t.s)
